mapper.select:
select DISTINCT matchamt.prod_id prodId, prodadd.PROD_MANAGER prodManager, sum((IFNULL(ptl.AMOUNT,0) + IFNULL(sec.matchamt,0))) openHighMobilityMol, sum((IFNULL(bvtd.MARKET_VALUE,IFNULL(bvtds.MARKET_VALUE,0))-IFNULL(bvtd1.MARKET_VALUE,IFNULL(bvtds1.MARKET_VALUE,0)))) openHighMobilityDen, sum((IFNULL(ptl.AMOUNT,0) + IFNULL(sec.matchamt,0))/(IFNULL(bvtd.MARKET_VALUE,IFNULL(bvtds.MARKET_VALUE,0))-IFNULL(bvtd1.MARKET_VALUE,IFNULL(bvtds1.MARKET_VALUE,0)))) openHighMobilityAsset FROM ( select PROD_ID,CDATE,MATCHTYPE from JL_ASSET_DEAL_MATCH_AMT GROUP BY PROD_ID,CDATE,MATCHTYPE ) matchamt left join fin_product prd on matchamt.prod_id = prd.FINPROD_MARKET_ID left join fin_product_add prodadd on prd.finprod_id = prodadd.finprod_id left join BOK_VAL_TABLE_DATA bvtd on bvtd.BOOKSET_ID = prd.finprod_id and bvtd.VAL_DATE = matchamt.CDATE and bvtd.DETAIL_DIST = '05' left join BOK_VAL_TABLE_DATA bvtd1 on bvtd1.BOOKSET_ID = prd.finprod_id and bvtd1.VAL_DATE = matchamt.CDATE and bvtd1.DETAIL_DIST = '06' left join BOK_VAL_TABLE_DATA bvtds on bvtds.BOOKSET_ID = matchamt.prod_id and bvtds.VAL_DATE = matchamt.CDATE and bvtds.DETAIL_DIST = '05' left join BOK_VAL_TABLE_DATA bvtds1 on bvtds1.BOOKSET_ID = matchamt.prod_id and bvtds1.VAL_DATE = matchamt.CDATE and bvtds1.DETAIL_DIST = '06' LEFT JOIN (select ptl.portfolio_id, ptl.CDATE,sum(ptl.AMOUNT) AMOUNT from PTL_CASH_POSITION ptl group by ptl.portfolio_id,ptl.CDATE) ptl on ptl.PORTFOLIO_ID = matchamt.prod_id and ptl.CDATE = matchamt.CDATE left join ( select matchamt.prod_id, sum(matchamt.matchamt) matchamt from jl_asset_deal_match_amt matchamt left join fin_product asset on matchamt.asset_code = asset.finprod_id left join fin_product_type fintype on asset.finprod_id = fintype.finprod_id where matchamt.cdate = STR_TO_DATE(#{searchDate,jdbcType=VARCHAR},'%Y-%m-%d') and matchamt.matchtype = '02' and fintype.type_10 in ('03', '04', '06') and asset.mdate < STR_TO_DATE(#{searchDate,jdbcType=VARCHAR},'%Y-%m-%d') + 365 group by matchamt.prod_id ) sec on sec.prod_id = matchamt.prod_id where matchamt.cdate = STR_TO_DATE(#{searchDate,jdbcType=VARCHAR},'%Y-%m-%d') and matchamt.matchtype = '02' and prd.OPERATION_TYPE = '02' AND prd.FINPROD_TYPE2 = 'F16' and IFNULL(bvtd.MARKET_VALUE,IFNULL(bvtds.MARKET_VALUE,0))-IFNULL(bvtd1.MARKET_VALUE,IFNULL(bvtds1.MARKET_VALUE,0))!=0
and prodadd.PROD_MANAGER in
#{item}
and matchamt.PROD_ID in
#{item}
group by matchamt.prod_id,prodadd.PROD_MANAGER

select DISTINCT matchamt.prod_id prodId, prodadd.PROD_MANAGER prodManager, sum((IFNULL(ptl.AMOUNT,0) + IFNULL(sec.matchamt,0))) openHighMobilityMol, sum((IFNULL(bvtd.MARKET_VALUE,IFNULL(bvtds.MARKET_VALUE,0))-IFNULL(bvtd1.MARKET_VALUE,IFNULL(bvtds1.MARKET_VALUE,0)))) openHighMobilityDen, sum((IFNULL(ptl.AMOUNT,0) + IFNULL(sec.matchamt,0))/(IFNULL(bvtd.MARKET_VALUE,IFNULL(bvtds.MARKET_VALUE,0))-IFNULL(bvtd1.MARKET_VALUE,IFNULL(bvtds1.MARKET_VALUE,0)))) openHighMobilityAsset FROM ( select PROD_ID,CDATE,MATCHTYPE from JL_ASSET_DEAL_MATCH_AMT GROUP BY PROD_ID,CDATE,MATCHTYPE ) matchamt left join fin_product prd on matchamt.prod_id = prd.FINPROD_MARKET_ID left join fin_product_add prodadd on prd.finprod_id = prodadd.finprod_id left join BOK_VAL_TABLE_DATA bvtd on bvtd.BOOKSET_ID = prd.finprod_id and bvtd.VAL_DATE = matchamt.CDATE and bvtd.DETAIL_DIST = '05' left join BOK_VAL_TABLE_DATA bvtd1 on bvtd1.BOOKSET_ID = prd.finprod_id and bvtd1.VAL_DATE = matchamt.CDATE and bvtd1.DETAIL_DIST = '06' left join BOK_VAL_TABLE_DATA bvtds on bvtds.BOOKSET_ID = matchamt.prod_id and bvtds.VAL_DATE = matchamt.CDATE and bvtds.DETAIL_DIST = '05' left join BOK_VAL_TABLE_DATA bvtds1 on bvtds1.BOOKSET_ID = matchamt.prod_id and bvtds1.VAL_DATE = matchamt.CDATE and bvtds1.DETAIL_DIST = '06' LEFT JOIN (select ptl.portfolio_id, ptl.CDATE,sum(ptl.AMOUNT) AMOUNT from PTL_CASH_POSITION ptl group by ptl.portfolio_id,ptl.CDATE) ptl on ptl.PORTFOLIO_ID = matchamt.prod_id and ptl.CDATE = matchamt.CDATE left join ( select matchamt.prod_id, sum(matchamt.matchamt) matchamt from ( select matchamt.PROD_ID, matchamt.CDATE, IFNULL(IFNULL(tp1.FINPROD_ID,pos.ASSET_CODE),matchamt.ASSET_CODE) ASSET_CODE, IFNULL(pos.TOTAL_NUM/MATCHAMT.matchamt*POS_AMT,matchamt.MATCHAMT) MATCHAMT from JL_ASSET_DEAL_MATCH_AMT matchamt left join FIN_PRODUCT tp ON matchamt.ASSET_CODE = tp.FINPROD_ID left join CHB_BOT_AST_POS_SUB pos ON tp.FINPROD_MARKET_ID = pos.PLAN_ASSET_ID AND matchamt.CDATE = pos.POS_DATE left join FIN_PRODUCT tp1 ON pos.ASSET_CODE = tp1.FINPROD_MARKET_ID where matchamt.CDATE = STR_TO_DATE(#{searchDate,jdbcType=VARCHAR},'%Y-%m-%d') and matchamt.MATCHTYPE ='01' ) matchamt left join fin_product asset on matchamt.asset_code = asset.finprod_id left join fin_product_type fintype on asset.finprod_id = fintype.finprod_id where matchamt.cdate = STR_TO_DATE(#{searchDate,jdbcType=VARCHAR},'%Y-%m-%d') and fintype.type_10 in ('03', '04', '06') and asset.mdate < STR_TO_DATE(#{searchDate,jdbcType=VARCHAR},'%Y-%m-%d') + 365 group by matchamt.prod_id ) sec on sec.prod_id = matchamt.prod_id where matchamt.cdate = STR_TO_DATE(#{searchDate,jdbcType=VARCHAR},'%Y-%m-%d') and matchamt.matchtype = '02' and prd.OPERATION_TYPE = '02' AND prd.FINPROD_TYPE2 = 'F16' and IFNULL(bvtd.MARKET_VALUE,IFNULL(bvtds.MARKET_VALUE,0))-IFNULL(bvtd1.MARKET_VALUE,IFNULL(bvtds1.MARKET_VALUE,0))!=0
and prodadd.PROD_MANAGER in
#{item}
and matchamt.PROD_ID in
#{item}
group by matchamt.prod_id,prodadd.PROD_MANAGER

select T5.PORTFOLIO_ID prodId, T5.PROD_MANAGER prodManager, sum(pos.amount) cash from ptl_cash_position pos LEFT JOIN Fin_Product_Add T5 ON T5.PORTFOLIO_ID = pos.PORTFOLIO_ID LEFT JOIN STL_FIN_PRODUCT_ACCT PTL on pos.acct_id = ptl.acct_no and T5.FINPROD_ID = PTL.FINPROD_ID where pos.cdate = STR_TO_DATE(#{searchDate,jdbcType=VARCHAR},'%Y-%m-%d') and PTL.ACCT_TYPE = 'A01'
and T5.PROD_MANAGER in
#{item}
and T5.PORTFOLIO_ID in
#{item}
group by T5.PORTFOLIO_ID,T5.PROD_MANAGER

SELECT PROD_ID prodId, PROD_MANAGER prodManager, SUM(UNINVEST_CASH) cashPierce FROM( select DISTINCT pos.UNINVEST_CASH, del.PROD_ID, padd.PROD_MANAGER from chb_bot_ast_pos pos INNER JOIN ( SELECT DISTINCT ASSET_CODE, deal.PROD_ID FROM chb_invest_trade deal left join CHB_PRD_BASEINFO prd on prd.PROD_ID=deal.PROD_ID and prd.status !='D' where deal.trade_type='05' and deal.status !='D' and prd.PROFIT_TYPE='03' ) del ON del.ASSET_CODE = pos.PLAN_ASSET_ID LEFT JOIN Fin_Product_Add padd ON padd.PORTFOLIO_ID = del.PROD_ID where pos.pos_date=STR_TO_DATE(#{searchDate,jdbcType=VARCHAR},'%Y-%m-%d') and pos.status !='D'
and padd.PROD_MANAGER in
#{item}
and del.PROD_ID in
#{item}
) group by PROD_ID,PROD_MANAGER

select DISTINCT matchamt.prod_id prodId, prodadd.PROD_MANAGER prodManager, sum((IFNULL(ptl.AMOUNT,0) + IFNULL(sec.matchamt,0))) highMobilityMol, sum((IFNULL(bvtd.MARKET_VALUE,IFNULL(bvtds.MARKET_VALUE,0))-IFNULL(bvtd1.MARKET_VALUE,IFNULL(bvtds1.MARKET_VALUE,0)))) highMobilityDen, sum((IFNULL(ptl.AMOUNT,0) + IFNULL(sec.matchamt,0))/(IFNULL(bvtd.MARKET_VALUE,IFNULL(bvtds.MARKET_VALUE,0))-IFNULL(bvtd1.MARKET_VALUE,IFNULL(bvtds1.MARKET_VALUE,0)))) highMobilityAsset FROM JL_ASSET_DEAL_MATCH_AMT matchamt left join fin_product prd on matchamt.prod_id = prd.FINPROD_MARKET_ID left join fin_product_add prodadd on prd.finprod_id = prodadd.finprod_id left join BOK_VAL_TABLE_DATA bvtd on bvtd.BOOKSET_ID = prd.finprod_id and bvtd.VAL_DATE = matchamt.CDATE and bvtd.DETAIL_DIST = '05' left join BOK_VAL_TABLE_DATA bvtd1 on bvtd1.BOOKSET_ID = prd.finprod_id and bvtd1.VAL_DATE = matchamt.CDATE and bvtd1.DETAIL_DIST = '06' left join BOK_VAL_TABLE_DATA bvtds on bvtds.BOOKSET_ID = matchamt.prod_id and bvtds.VAL_DATE = matchamt.CDATE and bvtds.DETAIL_DIST = '05' left join BOK_VAL_TABLE_DATA bvtds1 on bvtds1.BOOKSET_ID = matchamt.prod_id and bvtds1.VAL_DATE = matchamt.CDATE and bvtds1.DETAIL_DIST = '06' LEFT JOIN (select ptl.portfolio_id, ptl.CDATE,sum(ptl.AMOUNT) AMOUNT from PTL_CASH_POSITION ptl group by ptl.portfolio_id,ptl.CDATE ) ptl on ptl.PORTFOLIO_ID = matchamt.prod_id and ptl.CDATE = matchamt.CDATE left join ( select matchamt.ASSET_CODE ASSET_CODE, sum(matchamt.matchamt) matchamt from jl_asset_deal_match_amt matchamt left join fin_product_type fintype on matchamt.prod_id = fintype.finprod_id left join fin_product asset on matchamt.asset_code = asset.finprod_id left join fin_product prd on matchamt.prod_id = prd.FINPROD_MARKET_ID LEFT JOIN (select t.O_CODE, T.GRADE_ORG_ID, t.grade_result from (select t.*, @rownum:=@rownum+1 rownum, if(@O_CODE=t.O_CODE,@rank:=@rank+1,@rank:=1) as rnum from (SELECT * from MST_BOND_CREDIT_RATING order by O_CODE,GRADE_DATE desc)t, (select @rownum:=0,@O_CODE:=null,@rank:=0)b where t.IS_RECOMMAND = '01' and t.O_TYPE = '02' and t.GRADE_DATE <= STR_TO_DATE(#{searchDate,jdbcType=VARCHAR},'%Y-%m-%d')) t where rnum = 1) ZXRATING ON ASSET.FINPROD_MARKET_ID = ZXRATING.O_CODE where matchamt.cdate = STR_TO_DATE(#{searchDate,jdbcType=VARCHAR},'%Y-%m-%d') and matchamt.matchtype = '01' and (fintype.type_10 in ('03', '04', '06') or (ZXRATING.grade_result in ('01','02') and asset.issue_type = '01')) and prd.FINPROD_TYPE2 = 'F16' and prd.OPERATION_TYPE = '01' group by matchamt.ASSET_CODE ) sec on sec.ASSET_CODE = matchamt.ASSET_CODE where matchamt.cdate = STR_TO_DATE(#{searchDate,jdbcType=VARCHAR},'%Y-%m-%d') and matchamt.matchtype = '02' and prd.FINPROD_TYPE2 = 'F16' and prd.OPERATION_TYPE = '01' and prd.FINPROD_TYPE2 = 'F16' and (IFNULL(ptl.AMOUNT,0) + IFNULL(sec.matchamt,0)) !=0 and IFNULL(bvtd.MARKET_VALUE,IFNULL(bvtds.MARKET_VALUE,0))-IFNULL(bvtd1.MARKET_VALUE,IFNULL(bvtds1.MARKET_VALUE,0))!=0
and prodadd.PROD_MANAGER in
#{item}
and matchamt.PROD_ID in
#{item}
group by matchamt.prod_id,prodadd.PROD_MANAGER

