select prodId,prodManager,max(largestFinancierCD) largestFinancierCD from ( select matchamt.prod_id prodId, padd.PROD_MANAGER prodManager, asset.MANAGER manager, sum(matchamt.MATCHAMT) largestFinancierCD from jl_asset_deal_match_amt matchamt LEFT JOIN fin_product prd ON prd.FINPROD_MARKET_ID = matchamt.PROD_ID left join fin_product_add padd on prd.FINPROD_ID = padd.FINPROD_ID left join fin_product_type ptype on matchamt.asset_code = ptype.finprod_id LEFT JOIN TRD_PRODUCT_DEAL DEAL ON matchamt.TRADE_ID = DEAL.TRADE_ID left join ( select FINPROD_ID asset_code, COUNTER_ID MANAGER from TRD_PRODUCT_DEAL where FINPROD_TYPE2 IN ('F02','F03','F04','F05','F08','F09') union all select FINPROD_ID asset_code, ISSUER MANAGER from FIN_PRODUCT where FINPROD_TYPE2 IN ('F01','F07') union all select FINPROD_ID asset_code, MANAGER MANAGER from FIN_PRODUCT where FINPROD_TYPE2 IN ('F17','F06','F27') union all select FINPROD_ID asset_code, FINANCIER MANAGER from FIN_PRODUCT where FINPROD_TYPE2 IN ('F18') ) asset on matchamt.asset_code = asset.asset_code where matchamt.matchtype = '02' AND prd.FINPROD_TYPE2 = 'F16' and matchamt.cdate = STR_TO_DATE(#{searchDate,jdbcType=VARCHAR},'%Y-%m-%d') AND (deal.MDATE >= STR_TO_DATE(#{searchDate,jdbcType=VARCHAR},'%Y-%m-%d') OR deal.MDATE IS NULL) group by matchamt.prod_id,asset.MANAGER,padd.PROD_MANAGER ) ss where 1=1
