SELECT deal.FINPROD_ID prodId, padd.PROD_MANAGER prodManager, max(DEAL.TRADE_AMT / matchall.matchamt)*100 singlejoinratio FROM trd_product_deal deal LEFT JOIN FIN_PRODUCT fp ON deal.FINPROD_ID = fp.FINPROD_ID left join fin_product_add padd on fp.finprod_id = padd.finprod_id LEFT JOIN INF_ORG_CORRELATION org ON org.cor_orgid = FP.ISSUER OR org.cor_orgid = FP.FINANCIER OR org.cor_orgid = FP.MANAGER OR org.cor_orgid = FP.SPONSOR OR org.cor_orgid = FP.INVEST_ADVISER left join (select prod_id prodId,sum(matchamt) matchamt from jl_asset_deal_match_amt where cdate = STR_TO_DATE(#{searchDate,jdbcType=VARCHAR},'%Y-%m-%d') group by prod_id ) matchall on fp.FINPROD_ID = matchall.prodId WHERE org.cor_orgid IS NOT NULL and deal.IS_CANCEL = 'N' and deal.TRADE_STATUS = '01' AND PS IN ('T01', 'T05') and deal.settle_date <= STR_TO_DATE(#{searchDate,jdbcType=VARCHAR},'%Y-%m-%d')
and padd.PROD_MANAGER in
#{item}
and matchamt.prod_id in
#{item}
group by deal.FINPROD_ID,padd.PROD_MANAGER

select matchamt.prod_id prodId, padd.PROD_MANAGER prodManager, sum(matchamt.matchamt) nonPublicBondCD from jl_asset_deal_match_amt matchamt left join fin_product asset on matchamt.asset_code = asset.finprod_id left join fin_product prd on matchamt.prod_id = prd.FINPROD_MARKET_ID left join fin_product_add padd on prd.finprod_id = padd.finprod_id where matchamt.cdate = STR_TO_DATE(#{searchDate,jdbcType=VARCHAR},'%Y-%m-%d') and matchamt.matchtype = '01' and asset.finprod_type2 = 'F01' and prd.FINPROD_TYPE2 = 'F16' and asset.ISSUE_TYPE = '02'
and padd.PROD_MANAGER in
#{item}
and matchamt.prod_id in
