select matchamt.prod_id prodId, padd.PROD_MANAGER prodManager, sum(matchamt.matchamt) nonPublicBondCD from ( SELECT matchamt.PROD_ID, matchamt.CDATE, IFNULL(tp1.FINPROD_ID,matchamt.ASSET_CODE) ASSET_CODE, IFNULL(pos.TOTAL_NUM/matchamt.MATCHQTY*POS_AMT,matchamt.MATCHAMT) MATCHAMT FROM JL_ASSET_DEAL_MATCH_AMT matchamt LEFT JOIN FIN_PRODUCT tp ON matchamt.ASSET_CODE = tp.FINPROD_ID LEFT JOIN CHB_BOT_AST_POS_SUB pos ON tp.FINPROD_MARKET_ID = pos.PLAN_ASSET_ID AND matchamt.CDATE = pos.POS_DATE LEFT JOIN FIN_PRODUCT tp1 ON pos.ASSET_CODE = tp1.FINPROD_MARKET_ID WHERE matchamt.CDATE = STR_TO_DATE(#{searchDate,jdbcType=VARCHAR},'%Y-%m-%d') AND matchamt.MATCHTYPE ='01' ) matchamt left join fin_product asset on matchamt.asset_code = asset.finprod_id left join fin_product prd on matchamt.prod_id = prd.FINPROD_MARKET_ID left join fin_product_add padd on prd.finprod_id = padd.finprod_id where matchamt.cdate = STR_TO_DATE(#{searchDate,jdbcType=VARCHAR},'%Y-%m-%d') and asset.finprod_type2 = 'F01' and prd.FINPROD_TYPE2 = 'F16' and asset.ISSUE_TYPE = '02'
and padd.PROD_MANAGER in
#{item}
and matchamt.prod_id in
#{item}
group by matchamt.prod_id,padd.PROD_MANAGER

select MAX(sum(singleNonStandardrRatio)) singleNonStandardrRatio FROM (select matchamt.prod_id prodId, padd.PROD_MANAGER prodManager, asset.MANAGER, sum(matchamt.matchamt) singleNonStandardrRatio from jl_asset_deal_match_amt matchamt left join fin_product_type fintype on matchamt.ASSET_CODE = fintype.finprod_id left join fin_product_add padd on matchamt.PROD_ID = padd.portfolio_id left join ( select FINPROD_ID asset_code, COUNTER_ID MANAGER from TRD_PRODUCT_DEAL where FINPROD_TYPE2 IN ('F02','F03','F04','F05','F08','F09') union all select FINPROD_ID asset_code, ISSUER MANAGER from FIN_PRODUCT where FINPROD_TYPE2 IN ('F01','F07') union all select FINPROD_ID asset_code, MANAGER MANAGER from FIN_PRODUCT where FINPROD_TYPE2 IN ('F17','F06','F27') union all select FINPROD_ID asset_code, FINANCIER MANAGER from FIN_PRODUCT where FINPROD_TYPE2 IN ('F18') ) asset on matchamt.asset_code = asset.asset_code where matchamt.cdate = STR_TO_DATE(#{searchDate,jdbcType=VARCHAR},'%Y-%m-%d') and matchamt.matchtype = '01' and fintype.type_9 in ('09')
and padd.PROD_MANAGER in
#{item}
