SELECT matchamt.PROD_ID prodId, prdadd.PROD_MANAGER prodManager, SUM(IFNULL(val.tdy_float_ingpl, 0)*matchamt.MATCHQTY) tdyFloatIngplMol, SUM(matchamt.MATCHQTY) tdyFloatIngplDen, SUM(IFNULL(val.tdy_float_ingpl, 0)*matchamt.MATCHQTY)/SUM(matchamt.MATCHQTY) tdyFloatIngpl FROM jl_asset_deal_match_amt matchamt LEFT JOIN ptl_sec_valution val ON matchamt.ASSET_CODE = val.FINPROD_ID AND matchamt.CDATE = val.CDATE AND matchamt.PROD_ID =val.PORTFOLIO_ID LEFT JOIN fin_product asset ON val.finprod_id = asset.finprod_id LEFT JOIN fin_product prd ON prd.FINPROD_MARKET_ID = matchamt.PROD_ID LEFT JOIN fin_product_add prdadd ON prd.FINPROD_ID = prdadd.FINPROD_ID where matchamt.cdate = STR_TO_DATE(#{searchDate,jdbcType=VARCHAR},'%Y-%m-%d') and matchamt.matchtype = '02' and IFNULL(val.tdy_float_ingpl, 0) !=0 and asset.finprod_type2 = 'F01' and prd.FINPROD_TYPE2 = 'F16'
