group by matchamt.PROD_ID,prdadd.PROD_MANAGER UNION ALL SELECT matchamt.PROD_ID prodId, prdadd.PROD_MANAGER prodManager, sum(((IFNULL(mb.NETPRICE,0) - IFNULL(sub.UNIT_COST,0))*matchamt.MATCHQTY/100*matchamt.MATCHQTY)) tdyFloatIngplMol, SUM(matchamt.MATCHQTY) tdyFloatIngplDen, sum((IFNULL(mb.NETPRICE,0) - IFNULL(sub.UNIT_COST,0))*matchamt.MATCHQTY/100*matchamt.MATCHQTY)/SUM(matchamt.MATCHQTY) tdyFloatIngpl FROM( select matchamt.PROD_ID, matchamt.CDATE, IFNULL(IFNULL(tp1.FINPROD_ID,pos.ASSET_CODE),matchamt.ASSET_CODE) ASSET_CODE, IFNULL(pos.TOTAL_NUM/matchamt.MATCHQTY*POS_NUM,matchamt.MATCHQTY) MATCHQTY from JL_ASSET_DEAL_MATCH_AMT matchamt left join FIN_PRODUCT tp ON matchamt.ASSET_CODE = tp.FINPROD_ID left join CHB_BOT_AST_POS_SUB pos ON tp.FINPROD_MARKET_ID = pos.PLAN_ASSET_ID AND matchamt.CDATE = pos.POS_DATE left join FIN_PRODUCT tp1 ON pos.ASSET_CODE = tp1.FINPROD_MARKET_ID where matchamt.CDATE = STR_TO_DATE(#{searchDate,jdbcType=VARCHAR},'%Y-%m-%d') and matchamt.MATCHTYPE ='01' AND pos.ASSET_CODE IS NOT NULL ) matchamt LEFT JOIN fin_product asset ON matchamt.ASSET_CODE = asset.finprod_id LEFT JOIN fin_product prd ON prd.FINPROD_MARKET_ID = matchamt.PROD_ID LEFT JOIN fin_product_add prdadd ON prd.FINPROD_ID = prdadd.FINPROD_ID left join RSK_VALTBL_ASSET_SUB sub on matchamt.ASSET_CODE = sub.FINPROD_ID AND matchamt.CDATE = sub.VAL_DATE left join (select t.SEC_ID, t.NETPRICE from ( select mb.*, @rownum:=@rownum+1 rownum, @SEC_ID=mb.SEC_ID, if(@SEC_ID=mb.SEC_ID,@rank:=@rank+1,@rank:=1) as rnum from(SELECT * from MST_BOND_VALUATION_INFO order by SEC_ID,VALUE_DATE DESC)mb, (select @rownum:=0,@SEC_ID:=null,@rank:=0)b where mb.VALUE_DATE <= STR_TO_DATE(#{searchDate,jdbcType=VARCHAR},'%Y-%m-%d') ) t where rnum = 1) mb on mb.SEC_ID = asset.FINPROD_MARKET_ID WHERE matchamt.cdate = STR_TO_DATE(#{searchDate,jdbcType=VARCHAR},'%Y-%m-%d') AND asset.finprod_type2 = 'F01' AND prd.FINPROD_TYPE2 = 'F16'
