SELECT DISTINCT matchamt.PROD_ID prodId, PRODADD.PROD_MANAGER prodManager, SUM(IFNULL(assetDuration,0) * matchamt.MATCHQTY) secDurationMol, SUM(matchamt.MATCHQTY) secDurationDel, SUM(IFNULL(assetDuration,0) * matchamt.MATCHQTY)/ SUM(matchamt.MATCHQTY) secDuration FROM JL_ASSET_DEAL_MATCH_AMT matchamt LEFT JOIN TRD_PRODUCT_DEAL dealori ON matchamt.trade_id = dealori.trade_id LEFT JOIN ( SELECT DISTINCT DEAL.FINPROD_ID ASSET_CODE, IFNULL(val.SDURATION,ptl.END_DAYS_2*365) assetDuration FROM TRD_PRODUCT_DEAL DEAL LEFT JOIN TRD_PRODUCT_DEAL_ADD DEALADD ON DEAL.TRADE_ID = DEALADD.TRADE_ID LEFT JOIN FIN_PRODUCT PROD ON DEAL.FINPROD_ID = PROD.FINPROD_ID LEFT JOIN( select val.SEC_ID,val.SDURATION from (select val.*, @rownum:=@rownum+1 rownum, if(@SEC_ID=val.SEC_ID,@rank:=@rank+1,@rank:=1) as rnum, @SEC_ID=val.SEC_ID from(SELECT * from MST_BOND_VALUATION_INFO order by SEC_ID,VALUE_DATE desc)val, (select @rownum:=0,@SEC_ID:=null,@rank:=0)b where val.VALUE_DATE <= STR_TO_DATE(#{searchDate,jdbcType=VARCHAR},'%Y-%m-%d') and val.SDURATION <> 0 AND val.SDURATION is not null ) val where rnum = 1) val ON PROD.FINPROD_MARKET_ID = val.SEC_ID LEFT JOIN PTL_SEC_VALUTION ptl ON PROD.FINPROD_ID = ptl.FINPROD_ID AND DEAL.TRADE_DATE = ptl.CDATE AND DEALADD.PORTFOLIO_ID = ptl.PORTFOLIO_ID WHERE 1=1 AND DEAL.IS_CANCEL ='N' AND DEAL.BUSI_TYPE = '02' AND DEAL.FINPROD_TYPE2 = 'F01' AND ( ABS(IFNULL(deal.share_amt,0)) + ABS(IFNULL(deal.trade_amt,0)) != 0) AND IFNULL(deal.p_trade_id,'NOREV') = 'NOREV' ) asset ON dealori.FINPROD_ID = asset.ASSET_CODE AND asset.assetDuration IS NOT NULL INNER JOIN FIN_PRODUCT PROD ON PROD.FINPROD_MARKET_ID = matchamt.PROD_ID LEFT JOIN FIN_PRODUCT_ADD PRODADD ON PRODADD.FINPROD_ID = PROD.FINPROD_ID left JOIN FIN_PRODUCT sec ON sec.FINPROD_ID = matchamt.ASSET_CODE left join (select t.portfolio_id, t.finprod_id, t.DSC_COST_AMT, t.SHARE_AMT, t.ACT_D_YIELD, t.tdy_float_ingpl from (select ptl.*,rnum from ( /* 子查询必加上rn字段 */ SELECT result.* FROM ( SELECT tmp.*, @rownum := @rownum + 1 row, /* 虚拟列行标 */ IF( ( @BOOKSET_ID = tmp.BOOKSET_ID and @BOK_DETAIL_ID = tmp.BOK_DETAIL_ID ), @rank := @rank + 1, @rank := 1 ) AS rnum, /* 分组虚拟列行标 */ /* 下面的分组条件需要与oracle中 over (PARTITION BY xxx,xxx,xxx)顺序保持一至 */ @portfolio_id := tmp.portfolio_id /* 分组条件1 */ , @finprod_id := tmp.finprod_id /* 分组条件2 */ FROM ( /* 数据源 */ SELECT bc.* FROM ptl_sec_valution bc ORDER BY ptl.cdate desc /* 按实际情况与oracle保持一至的排序 */ ) tmp, /* 定义临时变量池 */ (SELECT @rownum := 0, @portfolio_id := null, @finprod_id = null, @rank := 0) a ) result ) ptl where cdate <= STR_TO_DATE(#{searchDate,jdbcType=VARCHAR},'%Y-%m-%d') and ptl.SHARE_AMT <> 0 AND ptl.SHARE_AMT is not null ) t where rnum = 1) ptl on matchamt.prod_id = ptl.portfolio_id and matchamt.asset_code = ptl.finprod_id WHERE matchamt.MATCHTYPE = '02' AND PROD.FINPROD_TYPE2 = 'F16' AND asset.assetDuration != 0 AND matchamt.CDATE =STR_TO_DATE(#{searchDate,jdbcType=VARCHAR},'%Y-%m-%d') AND PROD.VDATE <= STR_TO_DATE(#{searchDate,jdbcType=VARCHAR},'%Y-%m-%d') AND PROD.MDATE > STR_TO_DATE(#{searchDate,jdbcType=VARCHAR},'%Y-%m-%d') AND ((dealori.FINPROD_TYPE2 not IN ('F03','F05','F09')and sec.finprod_market_id is not null) or(dealori.FINPROD_TYPE2 IN ('F03','F05','F09')and ptl.finprod_id is not null)) AND (( dealori.FINPROD_TYPE2 IN ('F10', 'F06', 'F17', 'F18')) OR ( dealori.FINPROD_TYPE2 NOT IN ('F10', 'F06', 'F17', 'F18') AND dealori.VDATE <= STR_TO_DATE(#{searchDate,jdbcType=VARCHAR},'%Y-%m-%d') AND dealori.MDATE >STR_TO_DATE(#{searchDate,jdbcType=VARCHAR},'%Y-%m-%d')))
AND PRODADD.PROD_MANAGER IN
#{item}
AND matchamt.PROD_ID IN
#{item}
GROUP BY matchamt.PROD_ID,PRODADD.PROD_MANAGER

SELECT DISTINCT matchamt.PROD_ID prodId, PRODADD.PROD_MANAGER prodManager, SUM(IFNULL(assetDuration,0) * matchamt.MATCHQTY) secDurationMol, SUM(matchamt.MATCHQTY) secDurationDel, SUM(IFNULL(assetDuration,0) * matchamt.MATCHQTY)/ SUM(matchamt.MATCHQTY) secDuration FROM( select matchamt.PROD_ID, matchamt.CDATE, IFNULL(tp1.FINPROD_ID,matchamt.ASSET_CODE) ASSET_CODE, IFNULL(pos.TOTAL_NUM/matchamt.MATCHQTY*POS_NUM,matchamt.MATCHQTY) MATCHQTY from JL_ASSET_DEAL_MATCH_AMT matchamt left join FIN_PRODUCT tp ON matchamt.ASSET_CODE = tp.FINPROD_ID left join CHB_BOT_AST_POS_SUB pos ON tp.FINPROD_MARKET_ID = pos.PLAN_ASSET_ID AND matchamt.CDATE = pos.POS_DATE left join FIN_PRODUCT tp1 ON pos.ASSET_CODE = tp1.FINPROD_MARKET_ID where matchamt.CDATE = STR_TO_DATE(#{searchDate,jdbcType=VARCHAR},'%Y-%m-%d') and matchamt.MATCHTYPE ='01' ) matchamt LEFT JOIN ( SELECT DISTINCT DEAL.FINPROD_ID ASSET_CODE, IFNULL(val.SDURATION,ptl.END_DAYS_2*365) assetDuration FROM TRD_PRODUCT_DEAL DEAL LEFT JOIN TRD_PRODUCT_DEAL_ADD DEALADD ON DEAL.TRADE_ID = DEALADD.TRADE_ID LEFT JOIN FIN_PRODUCT PROD ON DEAL.FINPROD_ID = PROD.FINPROD_ID LEFT JOIN( select val.SEC_ID,val.SDURATION from (select @rownum:=@rownum+1 rownum, val.*, if(@SEC_ID=val.SEC_ID,@rank:=@rank+1,@rank:=1) as rnum, @SEC_ID:=val.SEC_ID from(SELECT * from biz_qa_check_first order by orderchildId,CheckEndTimedesc)val, (select @rownum:=0,@SEC_ID:=null,@rank:=0)b where val.VALUE_DATE <= STR_TO_DATE(#{searchDate,jdbcType=VARCHAR},'%Y-%m-%d') and val.SDURATION <> 0 AND val.SDURATION is not null ) val where rnum = 1) val ON PROD.FINPROD_MARKET_ID = val.SEC_ID LEFT JOIN PTL_SEC_VALUTION ptl ON PROD.FINPROD_ID = ptl.FINPROD_ID AND DEAL.TRADE_DATE = ptl.CDATE AND DEALADD.PORTFOLIO_ID = ptl.PORTFOLIO_ID WHERE 1=1 AND DEAL.IS_CANCEL ='N' AND DEAL.BUSI_TYPE = '02' AND DEAL.FINPROD_TYPE2 = 'F01' AND ( ABS(IFNULL(deal.share_amt,0)) + ABS(IFNULL(deal.trade_amt,0)) != 0) AND IFNULL(deal.p_trade_id,'NOREV') = 'NOREV' ) asset ON matchamt.ASSET_CODE = asset.ASSET_CODE AND asset.assetDuration IS NOT NULL INNER JOIN FIN_PRODUCT PROD ON PROD.FINPROD_MARKET_ID = matchamt.PROD_ID LEFT JOIN FIN_PRODUCT_ADD PRODADD ON PRODADD.FINPROD_ID = PROD.FINPROD_ID left JOIN FIN_PRODUCT sec ON sec.FINPROD_ID = matchamt.ASSET_CODE left join (select t.portfolio_id, t.finprod_id, t.DSC_COST_AMT, t.SHARE_AMT, t.ACT_D_YIELD, t.tdy_float_ingpl from (select ptl.*, rnum
from ( /* 子查询必加上rn字段 */ SELECT result.* FROM ( SELECT tmp.*, @rownum := @rownum + 1 row, /* 虚拟列行标 */ IF( ( @portfolio_id = tmp.portfolio_id and @finprod_id = tmp.finprod_id
), @rank := @rank + 1, @rank := 1 ) AS rnum, /* 分组虚拟列行标 */ /* 下面的分组条件需要与oracle中 over (PARTITION BY xxx,xxx,xxx)顺序保持一至 */ @portfolio_id := tmp.portfolio_id /* 分组条件1 */ , @finprod_id := tmp.finprod_id /* 分组条件2 */
FROM ( /* 数据源 */ SELECT bc.* FROM ptl_sec_valution bc ORDER BY cdate desc /* 按实际情况与oracle保持一至的排序 */ ) tmp, /* 定义临时变量池 */ (SELECT @rownum := 0, @portfolio_id := null, @finprod_id = null, @rank := 0) a ) result ) ptl where cdate <= STR_TO_DATE(#{searchDate,jdbcType=VARCHAR},'%Y-%m-%d') and ptl.SHARE_AMT <> 0 AND ptl.SHARE_AMT is not null ) t where rnum = 1) ptl on matchamt.prod_id = ptl.portfolio_id and matchamt.asset_code = ptl.finprod_id WHERE PROD.FINPROD_TYPE2 = 'F16' AND asset.assetDuration != 0 AND matchamt.CDATE =STR_TO_DATE(#{searchDate,jdbcType=VARCHAR},'%Y-%m-%d') AND PROD.VDATE <= STR_TO_DATE(#{searchDate,jdbcType=VARCHAR},'%Y-%m-%d') AND PROD.MDATE > STR_TO_DATE(#{searchDate,jdbcType=VARCHAR},'%Y-%m-%d')
AND PRODADD.PROD_MANAGER IN
