SELECT PROD.FINPROD_MARKET_ID prodId, PRODADD.PROD_MANAGER prodManager, SUM(IFNULL(ptl.END_DAYS_2/365,0)) productDuration FROM FIN_PRODUCT PROD LEFT JOIN FIN_PRODUCT_ADD PRODADD ON PROD.FINPROD_ID = PRODADD.FINPROD_ID LEFT JOIN PTL_SEC_VALUTION ptl ON PRODADD.PORTFOLIO_ID = ptl.PORTFOLIO_ID LEFT JOIN REP_PROD_INFO repInfo ON PROD.FINPROD_MARKET_ID = repInfo.PROD_ID WHERE PROD.OPERATION_TYPE IN ('01','02') AND ptl.CDATE = STR_TO_DATE(#{searchDate,jdbcType=VARCHAR},'%Y-%m-%d')
