#{item}
GROUP BY PROD.FINPROD_MARKET_ID,PRODADD.PROD_MANAGER

select DISTINCT matchamt.prod_id prodId, prodadd.PROD_MANAGER prodManager, sum((IFNULL(bvtd.MARKET_VALUE,IFNULL(bvtds.MARKET_VALUE,0))-IFNULL(bvtd1.MARKET_VALUE,IFNULL(bvtds1.MARKET_VALUE,0)))) mobilityAssetSummary FROM ( select PROD_ID,CDATE,MATCHTYPE from JL_ASSET_DEAL_MATCH_AMT GROUP BY PROD_ID,CDATE,MATCHTYPE ) matchamt left join fin_product prd on matchamt.prod_id = prd.FINPROD_MARKET_ID left join fin_product_add prodadd on prd.finprod_id = prodadd.finprod_id left join BOK_VAL_TABLE_DATA bvtd on bvtd.BOOKSET_ID = prd.finprod_id and bvtd.VAL_DATE = matchamt.CDATE and bvtd.DETAIL_DIST = '05' left join BOK_VAL_TABLE_DATA bvtd1 on bvtd1.BOOKSET_ID = prd.finprod_id and bvtd1.VAL_DATE = matchamt.CDATE and bvtd1.DETAIL_DIST = '06' left join BOK_VAL_TABLE_DATA bvtds on bvtds.BOOKSET_ID = matchamt.prod_id and bvtds.VAL_DATE = matchamt.CDATE and bvtds.DETAIL_DIST = '05' left join BOK_VAL_TABLE_DATA bvtds1 on bvtds1.BOOKSET_ID = matchamt.prod_id and bvtds1.VAL_DATE = matchamt.CDATE and bvtds1.DETAIL_DIST = '06' where matchamt.cdate = STR_TO_DATE(#{searchDate,jdbcType=VARCHAR},'%Y-%m-%d') and matchamt.matchtype = '02' and prd.FINPROD_TYPE2 = 'F16' and IFNULL(bvtd.MARKET_VALUE,IFNULL(bvtds.MARKET_VALUE,0))-IFNULL(bvtd1.MARKET_VALUE,IFNULL(bvtds1.MARKET_VALUE,0))!=0
and prodadd.PROD_MANAGER in
#{item}
